  const issued1 = issueInvoice(draft, []).value;
  const totals1 = invoiceTotals(issued1);

  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  }).value;

  const issued2 = issueInvoice(draft2, ['INV-2026-0001']).value;
  const totals2 = invoiceTotals(issued2);
  const paymentAmount = 1000;
  const partial = recordPayment(issued2, { amount: paymentAmount, date: '2026-10-05' }).value;

  const invoices = [draft, issued1, partial];
  const r = dashboard(invoices, '2026-10-07');
  assert.equal(r.ok, true);
  const expected = totals1.total + (totals2.total - paymentAmount);
  assert.equal(r.value.outstanding, expected);
});

