test('dashboard identifies top customers by due amount', () => {
  const c1Draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  }).value;
  const c1Issued = issueInvoice(c1Draft, []).value;
  const c1Totals = invoiceTotals(c1Issued);

  const c2Draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  }).value;
  const c2Issued = issueInvoice(c2Draft, ['INV-2026-0001']).value;
  const c2Totals = invoiceTotals(c2Issued);
  const c2Partial = recordPayment(c2Issued, { amount: 1000, date: '2026-10-05' }).value;

  const c3Draft = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  }).value;
  const c3Issued = issueInvoice(c3Draft, ['INV-2026-0002']).value;

  const invoices = [c1Issued, c2Partial, c3Issued];
  const r = dashboard(invoices, '2026-10-07');
  assert.equal(r.ok, true);
  assert.equal(r.value.topCustomers.length, 3);
  assert.equal(r.value.topCustomers[0].customerId, 'C-001');
  assert.equal(r.value.topCustomers[0].due, c1Totals.total);
  assert.equal(r.value.topCustomers[1].customerId, 'C-003');
  assert.equal(r.value.topCustomers[2].customerId, 'C-002');
});

