      lines: [{ sku: 'DES-HOUR', qty: 9 }],
    }).value;
    const issued = issueInvoice(draft, invoices.map((inv) => inv.number).filter(Boolean)).value;
    invoices.push(issued);
  }

  const r = dashboard(invoices, '2026-10-07');
  assert.equal(r.ok, true);
  assert.equal(r.value.topCustomers.length, 3);
});

test('dashboard returns empty topCustomers if no issued/partially_paid', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  }).value;

  const invoices = [draft];
  const r = dashboard(invoices, '2026-10-07');
  assert.equal(r.ok, true);
  assert.deepEqual(r.value.topCustomers, []);
});

test('dashboard returns 0 overdue for empty invoices', () => {
  const r = dashboard([], '2026-10-07');
  assert.equal(r.ok, true);
  assert.equal(r.value.overdue.count, 0);
  assert.equal(r.value.overdue.amount, 0);
});

test('dashboard returns all fields', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  }).value;

  const issued = issueInvoice(draft, []).value;
  const invoices = [draft, issued];
  const r = dashboard(invoices, '2026-10-07');
  assert.equal(r.ok, true);
  assert.ok('counts' in r.value);
  assert.ok('outstanding' in r.value);
  assert.ok('overdue' in r.value);
  assert.ok('topCustomers' in r.value);
  assert.ok('count' in r.value.overdue);
  assert.ok('amount' in r.value.overdue);
});
